const body = $json || {};
const metadata = body.metadata || {};
const to = String(body.to || '').trim();
const subject = String(body.subject || '').trim();
const message = String(body.message || '').trim();

if (!to) throw new Error('Missing "to" email address');
if (!subject) throw new Error('Missing "subject"');
if (!message) throw new Error('Missing "message"');

const fromEmail = String(body.fromEmail || 'Envision Chess Academy <noreply@yourdomain.com>').trim();
const replyTo = String(body.replyTo || 'support@yourdomain.com').trim();
const preview = String(metadata.previewText || subject).trim();
const resetUrl = metadata.resetUrl ? String(metadata.resetUrl) : '';
const kind = String(metadata.kind || '').trim();

const escapeHtml = (value) => String(value || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');

const paragraphs = message
  .split(/\n+/)
  .map((line) => line.trim())
  .filter(Boolean)
  .map((line) => `<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#334155;">${escapeHtml(line)}</p>`)
  .join('');

const button = resetUrl
  ? `<div style="margin:26px 0 22px;"><a href="${escapeHtml(resetUrl)}" style="display:inline-block;background:#5a1372;color:#ffffff;text-decoration:none;padding:14px 24px;border-radius:12px;font-weight:700;font-size:15px;">Reset Password</a></div><p style="margin:0 0 14px;font-size:13px;line-height:1.6;color:#64748b;">If the button does not open, copy this link into your browser:</p><p style="margin:0 0 18px;font-size:13px;line-height:1.6;color:#5a1372;word-break:break-all;">${escapeHtml(resetUrl)}</p>`
  : '';

const headerLabel = kind === 'password_reset' ? 'Password Reset' : 'Academy Notification';
const htmlBody = `<!doctype html><html><body style="margin:0;padding:24px;background:#f8fafc;font-family:Arial,sans-serif;"><div style="max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e2e8f0;border-radius:22px;overflow:hidden;box-shadow:0 14px 40px rgba(15,23,42,0.08);"><div style="padding:22px 28px;background:linear-gradient(135deg,#5a1372 0%,#7d22a3 100%);color:#ffffff;"><div style="font-size:12px;font-weight:700;letter-spacing:0.16em;text-transform:uppercase;color:#fde75a;">${escapeHtml(headerLabel)}</div><h1 style="margin:10px 0 0;font-size:28px;line-height:1.2;font-weight:800;">${escapeHtml(subject)}</h1><p style="margin:10px 0 0;font-size:13px;line-height:1.6;color:#f5e9ff;">${escapeHtml(preview)}</p></div><div style="padding:28px;">${paragraphs}${button}<div style="margin-top:28px;padding-top:18px;border-top:1px solid #e2e8f0;font-size:12px;line-height:1.6;color:#64748b;">Envision Chess Academy<br/>This is an automated message from your academy platform.</div></div></div></body></html>`;

return [{ json: { to, subject, message, htmlBody, fromEmail, replyTo, metadata } }];
